"""Quick Build: many autogenerated characters in one go (owner 2026-09-24).

Each item is either a seed (the seed makes every choice, no AI) or a Local AI
build.  One worker walks the builds one after another; a second finalizes them,
because the Factory finalizes one character at a time and finalizing takes the
longest.  Batch progress is saved as plain JSON under ``<data>/quick_builds`` so
the tab can show it after a reload; builds that were running when the Factory
stopped are marked interrupted (their projects remain and can be resumed from
the normal build screen).
"""

from __future__ import annotations

import datetime as _dt
import json
import queue
import threading
import time
import uuid
from pathlib import Path
from typing import Any, Callable

from app.core import FoundryError

from .creative_controller import seeded_picker

ROUTE_SEEDED = "seeded"
ROUTE_LOCAL_AI = "local_ai"
TERMINAL = {"finished", "failed", "needs_review", "interrupted", "ready"}
MAX_ITEMS = 12


def _now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


class QuickBuildQueue:
    def __init__(
        self,
        directory: Path,
        *,
        create_project: Callable[..., dict[str, Any]],
        lock_choices: Callable[[str], Any],
        start_run: Callable[..., dict[str, Any]],
        finalize_run: Callable[[str], dict[str, Any]],
    ) -> None:
        self.directory = Path(directory)
        self._create_project = create_project
        self._lock_choices = lock_choices
        self._start_run = start_run
        self._finalize_run = finalize_run
        self._lock = threading.RLock()
        # Walks and finalizes take turns: a finalize's second isolated compilation
        # can disagree with the first when another build writes to the database
        # meanwhile (tournament 2026-09-24: CG1_NONDETERMINISTIC_COMPILATION).
        self._turn = threading.Lock()
        self._build_queue: queue.Queue[tuple[str, int]] = queue.Queue()
        self._finalize_queue: queue.Queue[tuple[str, int]] = queue.Queue()
        self._threads: list[threading.Thread] = []
        self._mark_interrupted()

    # ------------------------------------------------------------------ storage
    def _path(self, batch_id: str) -> Path:
        return self.directory / f"{batch_id}.json"

    def _read(self, batch_id: str) -> dict[str, Any]:
        return json.loads(self._path(batch_id).read_text(encoding="utf-8"))

    def _write(self, batch: dict[str, Any]) -> None:
        self.directory.mkdir(parents=True, exist_ok=True)
        batch["updated_at"] = _now()
        temporary = self._path(batch["batch_id"]).with_suffix(".tmp")
        temporary.write_text(json.dumps(batch, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
        temporary.replace(self._path(batch["batch_id"]))

    def _update(self, batch_id: str, index: int, **fields: Any) -> dict[str, Any]:
        with self._lock:
            batch = self._read(batch_id)
            batch["items"][index].update(fields)
            self._write(batch)
            return batch["items"][index]

    def _mark_interrupted(self) -> None:
        for path in sorted(self.directory.glob("*.json")) if self.directory.is_dir() else []:
            try:
                batch = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            changed = False
            for item in batch.get("items", []):
                if item.get("status") not in TERMINAL:
                    item.update(status="interrupted", message="The Factory stopped while this build was queued or running.")
                    changed = True
            if changed:
                self._write(batch)

    # ------------------------------------------------------------------ public
    def list(self, limit: int = 20) -> list[dict[str, Any]]:
        if not self.directory.is_dir():
            return []
        # Under the writers' lock: a directory listing taken while a batch file
        # is being renamed into place can skip it.
        with self._lock:
            batches = []
            for path in sorted(self.directory.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True)[:limit]:
                try:
                    batches.append(json.loads(path.read_text(encoding="utf-8")))
                except (OSError, ValueError):
                    continue
            return batches

    def submit(self, *, items: list[dict[str, Any]], target_cl: int, power_band: str = "rival/boss", finalize: bool = True) -> dict[str, Any]:
        if not items or len(items) > MAX_ITEMS:
            raise FoundryError("QUICK_BUILD_ITEMS_INVALID", f"Choose between 1 and {MAX_ITEMS} characters.", status_code=422)
        if not (1 <= int(target_cl) <= 20):
            raise FoundryError("QUICK_BUILD_CL_INVALID", "Cultivation level must be 1 to 20.", status_code=422)
        rows = []
        for item in items:
            route = item.get("route") or ROUTE_SEEDED
            seed = item.get("seed") or None
            if route not in {ROUTE_SEEDED, ROUTE_LOCAL_AI}:
                raise FoundryError("QUICK_BUILD_ROUTE_INVALID", "Each build is either seeded or Local AI.", status_code=422)
            if route == ROUTE_SEEDED:
                seed = seed or seeded_picker.new_seed()
                if not seeded_picker.valid_seed(seed):
                    raise FoundryError("QUICK_BUILD_SEED_INVALID", "A seed is 1-64 letters, digits, dots, dashes, colons or underscores.", status_code=422)
            rows.append({
                "route": route, "seed": seed if route == ROUTE_SEEDED else None,
                "concept": str(item.get("concept") or "")[:2000],
                "status": "queued", "message": "", "project_id": None, "run_id": None, "name": None,
                "walk_seconds": None, "finalize_seconds": None,
            })
        batch = {
            "schema": "TianxiaFoundry.QuickBuildBatch.v1", "batch_id": "qb." + uuid.uuid4().hex[:12],
            "target_cl": int(target_cl), "power_band": power_band, "finalize": bool(finalize),
            "created_at": _now(), "items": rows,
        }
        with self._lock:
            self._write(batch)
        self._ensure_workers()
        for index in range(len(rows)):
            self._build_queue.put((batch["batch_id"], index))
        return batch

    # ------------------------------------------------------------------ workers
    def _ensure_workers(self) -> None:
        with self._lock:
            if self._threads and all(thread.is_alive() for thread in self._threads):
                return
            self._threads = [
                threading.Thread(target=self._build_loop, name="quick-build-walk", daemon=True),
                threading.Thread(target=self._finalize_loop, name="quick-build-finalize", daemon=True),
            ]
            for thread in self._threads:
                thread.start()

    def _build_loop(self) -> None:
        while True:
            batch_id, index = self._build_queue.get()
            try:
                self._build(batch_id, index)
            except Exception as exc:  # noqa: BLE001 - reported on the item
                self._update(batch_id, index, status="failed", message=_message(exc), error_details=_details(exc))

    def _build(self, batch_id: str, index: int) -> None:
        batch = self._read(batch_id)
        item = batch["items"][index]
        self._update(batch_id, index, status="waiting_to_build", message="Waiting its turn (another character is finalizing).")
        # Creating the project and locking its choices write to the database too,
        # so they take the same turn as the walk.
        with self._turn:
            self._update(batch_id, index, status="building", message="Creating the project.")
            created = self._create_project(
                working_name="", concept=item.get("concept") or "", source_reference=None, target_cl=batch["target_cl"],
                power_band=batch["power_band"], creation_mode="quick", generation_route="ai_bootstrap",
                ability_scores={}, selections={}, sphere_priority_ids=[], talent_priority_ids=[],
                method_planning_mode="AUTO", method_preference_id=None, method_route_choice=None, method_learning_note=None,
                autogen_seed=item.get("seed"),
            )
            project_id = created["project_id"]
            self._update(batch_id, index, project_id=project_id,
                         message="Walking the build from the seed." if item.get("seed") else "The local AI is choosing.")
            self._lock_choices(project_id)
            started = time.time()
            run = self._start_run(project_id, execution_mode="STANDARD_API", idempotency_key=f"quick-build.{uuid.uuid4().hex}",
                                  controller_route="DETERMINISTIC_CREATIVE_CONTROLLER")
        fields = run.get("owner_descriptive_fields") or {}
        name = ((fields.get("resolved") or fields.get("proposed") or {}).get("identity") or {}).get("name")
        fields = {"run_id": run.get("run_id"), "walk_seconds": int(time.time() - started), "name": name}
        if run.get("status") != "READY_FOR_REVIEW":
            codes = sorted({str(row.get("code")) for row in run.get("blockers") or [] if isinstance(row, dict)})
            self._update(batch_id, index, status="needs_review", message=f"Stopped at {run.get('status')}: {', '.join(codes) or 'see the build screen'}.", **fields)
            return
        if not batch.get("finalize", True):
            self._update(batch_id, index, status="ready", message="Ready for review.", **fields)
            return
        self._update(batch_id, index, status="waiting_to_finalize", message="Waiting its turn to finalize.", **fields)
        self._finalize_queue.put((batch_id, index))

    def _finalize_loop(self) -> None:
        while True:
            batch_id, index = self._finalize_queue.get()
            try:
                self._finalize(batch_id, index)
            except Exception as exc:  # noqa: BLE001 - reported on the item
                self._update(batch_id, index, status="failed", message="Finalize: " + _message(exc), error_details=_details(exc))

    def _finalize(self, batch_id: str, index: int) -> None:
        item = self._read(batch_id)["items"][index]
        self._update(batch_id, index, status="finalizing", message="Finalizing (the longest step).")
        started = time.time()
        for _ in range(240):
            try:
                with self._turn:
                    final = self._finalize_run(item["run_id"])
                break
            except FoundryError as exc:
                if exc.code != "CG1_FINALIZATION_IN_PROGRESS":
                    raise
                time.sleep(15)  # another character (perhaps from the build screen) is finalizing
        else:
            raise FoundryError("QUICK_BUILD_FINALIZE_WAIT", "Another finalize kept the Factory busy for an hour.")
        status = final.get("status")
        self._update(batch_id, index, status="finished" if status == "CLEAN_AND_FINALIZED" else "needs_review",
                     message="Finished and installed." if status == "CLEAN_AND_FINALIZED" else f"Finalize ended at {status}.",
                     finalize_seconds=int(time.time() - started))


def _details(exc: Exception) -> Any:
    """The Factory's own error details, kept so a failed build can be diagnosed."""
    details = getattr(exc, "details", None)
    text = json.dumps(details, default=str) if details is not None else ""
    return json.loads(text) if text and len(text) <= 200_000 else (text[:200_000] or None)


def _message(exc: Exception) -> str:
    code = getattr(exc, "code", None)
    return (f"{code}: " if code else f"{type(exc).__name__}: ") + str(getattr(exc, "message", None) or exc)[:400]
